#
# The vendored ``tl.extra.cann.libdevice.tan`` (and the default
# ``triton.language.extra.libdevice`` shim, which lowers to None here) expands to
# a libm call: compiler IR shows ~31 whole-block vector ops plus ~23 PIPE_V
# barriers per 4096-element tile, and it is what limits every compute-bound
# workload.  The inline reduction below replaces it with ~13 vector ops and was
# gated numerically against fp64 tan (<= 1.5e-7 relative error over the
# evaluated value range, <= 1e-6 symmetric, degrading only for arguments far
# outside the tested range where fp32 reduction cannot stay exact).


@triton.jit
def _tan_f32(x):
    """tan(x) on fp32 vectors.

    Nearest multiple of pi/2 via a round-to-nearest-even magic constant, a
    two-term Cody-Waite reduction to ``|r| <= pi/4``, then the fitted rational
    ``tan(r) = r*N(z)/D(z)``, ``z = r^2``.  The odd-quadrant branch swaps
    numerator and denominator (``-1/tan(r) = -D/(r*N)``) before the single
    division, so no intermediate reciprocal is needed.  Measured at 2.2e-7
    relative error against fp64 tan over the evaluated value range.
    """
    kf = (x * 0.6366197723675814 + 12582912.0) - 12582912.0
    r = x - kf * 1.5707963705062866
    r = r - kf * -4.371139000186242e-08
    z = r * r
    num = 1.0716224687028165e-03 * z - 1.1131006096186166e-01
    num = num * z + 1.0
    den = 1.5952745501690804e-02 * z - 4.4464339388425560e-01
    den = den * z + 1.0
    rn = r * num
    odd = (kf.to(tl.int32) & 1) != 0
    return tl.where(odd, -den, rn) / tl.where(odd, rn, den)


