@triton.jit
def _tan_flat_kernel(x_ptr, n_elements, BLOCK: tl.constexpr):
    """Dense / non-overlapping-and-dense tensor visited in memory order."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    offs = tl.max_contiguous(tl.multiple_of(offs, BLOCK), BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    y = _tan_f32(x.to(tl.float32))
    tl.store(x_ptr + offs, y.to(x.dtype), mask=mask)


@triton.jit
def _tan_flat_kernel_i64(x_ptr, n_elements, BLOCK: tl.constexpr):
    pid = tl.program_id(0).to(tl.int64)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    y = _tan_f32(x.to(tl.float32))
    tl.store(x_ptr + offs, y.to(x.dtype), mask=mask)


@triton.jit
def _tan_fused4(
    p0,
    p1,
    p2,
    p3,
    n0,
    n1,
    n2,
    n3,
    DT: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Up to four disjoint flat tensors of one dtype in a single launch.

    Grid is ``(real_tensor_count, cdiv(max_numel, BLOCK))``; the base pointer and
    element count of the tensor this program owns are selected from the int64
    scalar arguments, so no device-side metadata buffer or H2D copy is needed.
    """
    t = tl.program_id(0)
    off = tl.program_id(1) * BLOCK + tl.arange(0, BLOCK)
    p = p0
    p = tl.where(t == 1, p1, p)
    p = tl.where(t == 2, p2, p)
    p = tl.where(t == 3, p3, p)
    n = n0
    n = tl.where(t == 1, n1, n)
    n = tl.where(t == 2, n2, n)
    n = tl.where(t == 3, n3, n)
    base = p.to(tl.pointer_type(DT))
    mask = off < n
    x = tl.load(base + off, mask=mask, other=0.0)
    y = _tan_f32(x.to(tl.float32))
    tl.store(base + off, y.to(x.dtype), mask=mask)


