@triton.jit
def _tan_strided_kernel(
    x_ptr,
    n_elements,
    SHAPE: tl.constexpr,
    STRIDES: tl.constexpr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Generic strided in-place tan over the logical (row-major) index space.

    ``SHAPE`` / ``STRIDES`` arrive reversed (inner dimension first) so the
    logical flat index decomposes with a single div/mod chain.
    """
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n_elements
    rem = tl.where(mask, idx, 0).to(tl.int64)
    off = tl.zeros([BLOCK], dtype=tl.int64)
    for i in tl.static_range(0, RANK):
        d = SHAPE[i]
        off += (rem % d) * STRIDES[i]
        rem = rem // d
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    y = _tan_f32(x.to(tl.float32))
    tl.store(x_ptr + off, y.to(x.dtype), mask=mask)


@triton.jit
def _tan_slice_kernel(
    x_ptr,
    n_elements,
    SHAPE: tl.constexpr,
    STRIDES: tl.constexpr,
    RANK: tl.constexpr,
    OFFSET: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Strided tan for one outer slice offset (rank > _MAX_RANK fallback)."""
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n_elements
    rem = tl.where(mask, idx, 0).to(tl.int64)
    off = tl.full([BLOCK], OFFSET, dtype=tl.int64)
    for i in tl.static_range(0, RANK):
        d = SHAPE[i]
        off += (rem % d) * STRIDES[i]
        rem = rem // d
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    y = _tan_f32(x.to(tl.float32))
    tl.store(x_ptr + off, y.to(x.dtype), mask=mask)


# ---------------------------------------------------------------------------
# host helpers (metadata only, no device work)
# ---------------------------------------------------------------------------


def _check_list(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
    return list(self)


def _reject_dtype(dtype):
    name = str(dtype).replace("torch.", "").capitalize()
    raise RuntimeError(
        f"result type Float can't be cast to the desired output type {name}"
    )


def _is_flat_addressable(t, n):
    """True when [data_ptr, data_ptr + numel) covers exactly this tensor.

    Called only for tensors that already failed ``is_contiguous``, so the
    contiguous fast path is not repeated here.
    """
    if n <= 1:
        return True
    expected = 1
    for stride, size in sorted(
        (s, sz) for s, sz in zip(t.stride(), t.shape) if sz != 1
    ):
        if stride != expected:
            return False
        expected *= size
    return True


def _collapse(shape, strides):
    """Merge adjacent dims that walk memory contiguously.

    Dims ``k`` (outer) and ``k+1`` (inner) merge only when
    ``strides[k] == strides[k+1] * shape[k+1]``; the merged dim keeps the inner
    stride, which is what preserves the exact address mapping.
    """
    dims = [(sz, st) for sz, st in zip(shape, strides) if sz != 1]
    out = []
    for sz, st in dims:
        if out and out[-1][1] == st * sz:
            psz, _ = out[-1]
            out[-1] = (psz * sz, st)
        else:
            out.append((sz, st))
    return [d[0] for d in out], [d[1] for d in out]


def _has_internal_overlap(t):
    for sz, st in zip(t.shape, t.stride()):
        if sz > 1 and st == 0:
            return True
    return False


def _bounding_span(t):
    """Conservative element span touched by an elementwise pass over a view."""
    span = 1
    for sz, st in zip(t.shape, t.stride()):
        if sz > 1:
            span += (sz - 1) * st
    return span


def _overlapping(spans):
    spans = sorted(spans)
    for i in range(1, len(spans)):
        if spans[i][0] < spans[i - 1][1]:
            return True
    return False


def _contiguous_run(ptrs, counts, itemsize):
    """True when equal-numel flat tensors tile one contiguous memory run.

    The check is metadata only: tensor ``i`` must have the same element count as
    the first and start exactly ``i`` spans after it.  A real allocator hands out
    same-sized blocks back to back often enough that this fires for the common
    "list of same-shape tensors" case, and then the whole group is one flat
    array: a 3-argument launch instead of the 16-pointer selecting kernel.
    """
    n = counts[0]
    span = n * itemsize
    base = ptrs[0]
    for i in range(1, len(ptrs)):
        if counts[i] != n or ptrs[i] != base + i * span:
            return False
    return True


def _launch_one(t, n, flat):
    """One launch for a single tensor."""
    block = _BLOCK
    if flat:
        grid = ((n + block - 1) // block,)
        if n < _I32_LIMIT:
            _tan_flat_kernel[grid](t, n, block)
        else:
            _tan_flat_kernel_i64[grid](t, n, block)
        return
    shape, strides = _collapse(t.shape, t.stride())
    if len(shape) <= _MAX_RANK:
        _tan_strided_kernel[((n + block - 1) // block,)](
            t, n, tuple(reversed(shape)), tuple(reversed(strides)), len(shape), block
        )
        return
    # Extremely high rank non-dense view: walk the outer dimensions on the
    # host, one launch per slice, so indexing never needs more than 8 dims.
    cut = len(shape) - _MAX_RANK
    outer = shape[:cut]
    inner_shape = shape[cut:]
    inner_strides = strides[cut:]
    inner_n = 1
    for sz in inner_shape:
        inner_n *= sz
    inner_rev = tuple(reversed(inner_shape))
    inner_str_rev = tuple(reversed(inner_strides))
    block = min(_BLOCK, max(64, triton.next_power_of_2(inner_n)))
    grid = ((inner_n + block - 1) // block,)
    for offs in _outer_offsets(outer, strides[:cut]):
        _tan_slice_kernel[grid](
            t, inner_n, inner_rev, inner_str_rev, len(inner_shape), int(offs), block
        )


def _launch_fused(ts, counts):
    """One launch for a dtype group of disjoint flat tensors."""
    block = _BLOCK
    nt = len(ts)
    dt = _TL_DTYPE[ts[0].dtype]
    ptrs = [int(t.data_ptr()) for t in ts]
    max_n = max(counts)
    same = all(c == max_n for c in counts)
    grid = (nt, (max_n + block - 1) // block)
    if nt <= 4:
        if same:
            while len(ptrs) < 4:
                ptrs.append(ptrs[0])
            _tan_fused4_eq[grid](*ptrs, max_n, dt, block)
            return
        while len(ptrs) < 4:
            ptrs.append(ptrs[0])
            counts.append(0)
        _tan_fused4[grid](*ptrs, *counts, dt, block)
        return
    if same:
        while len(ptrs) < _FUSE_MAX:
            ptrs.append(ptrs[0])
        _tan_fused16_eq[grid](*ptrs, max_n, dt, block)
        return
    while len(ptrs) < _FUSE_MAX:
        ptrs.append(ptrs[0])
        counts.append(0)
    _tan_fused16[grid](*ptrs, *counts, dt, block)


def _outer_offsets(outer_shape, outer_strides):
    if not outer_shape:
        yield 0
        return
    total = 1
    for sz in outer_shape:
        total *= sz
    for flat in range(total):
        rem = flat
        off = 0
        for sz, st in zip(reversed(outer_shape), reversed(outer_strides)):
            off += (rem % sz) * st
            rem //= sz
        yield off


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------


def foreach_tan_(self):
    tensors = _check_list(self)

    # Single pass: validate the whole list (ATen validates before mutating) and
    # cache every metadata fact the launch decision needs.  A contiguous tensor
    # cannot alias itself (every size>1 dim carries its canonical non-zero
    # stride), so the overlap probe is only needed for views.
    live = []
    counts = []
    flats = []
    ptrs = []
    spans = []
    dtype0 = None
    uniform = True
    for t in tensors:
        dtype = t.dtype
        if not dtype.is_floating_point:
            _reject_dtype(dtype)
        n = t.numel()
        if not n:
            continue
        if t.is_contiguous():
            flat = True
            span = n
        else:
            if _has_internal_overlap(t):
                raise RuntimeError(
                    "unsupported operation: more than one element of the "
                    "written-to tensor refers to a single memory location. "
                    "Please clone() the tensor before performing the operation."
                )
            flat = _is_flat_addressable(t, n)
            span = n if flat else _bounding_span(t)
        ptr = int(t.data_ptr())
        live.append(t)
        counts.append(n)
        flats.append(flat)
        ptrs.append(ptr)
        spans.append((ptr, ptr + span * dtype.itemsize))
        if dtype0 is None:
            dtype0 = dtype
        elif dtype is not dtype0:
            uniform = False
    if not live:
        return None

    if len(live) > 1 and _overlapping(spans):
        # Overlapping list entries: ATen applies tan left to right, so each
        # element needs its own ordered launch.
        for t, n, flat in zip(live, counts, flats):
            _launch_one(t, n, flat)
        return None

    nt = len(live)
    if uniform and all(flats):
        # Common case: one dtype, every element flat.  One launch, no grouping.
        n0 = counts[0]
        if nt == 1:
            _launch_one(live[0], n0, True)
        elif _contiguous_run(ptrs, counts, dtype0.itemsize):
            _launch_one(live[0], n0 * nt, True)
        elif nt <= _FUSE_MAX:
            _launch_fused(live, counts)
        else:
            for t, n in zip(live, counts):
                _launch_one(t, n, True)
        return None

    groups = {}
    strided = []
    for t, n, flat in zip(live, counts, flats):
        if flat:
            groups.setdefault(t.dtype, []).append((t, n))
        else:
            strided.append((t, n))

    for items in groups.values():
        if len(items) == 1:
            _launch_one(items[0][0], items[0][1], True)
        elif _contiguous_run(
            [it[0].data_ptr() for it in items],
            [it[1] for it in items],
            items[0][0].dtype.itemsize,
        ):
            _launch_one(items[0][0], items[0][1] * len(items), True)
        elif len(items) <= _FUSE_MAX:
            _launch_fused([it[0] for it in items], [it[1] for it in items])
        else:
            for t, n in items:
                _launch_one(t, n, True)

    for t, n in strided:
        _launch_one(t, n, False)
    return None
